import{z as i,x as D,o as t,c as A,q as n,j as s,D as e,d as r,s as B,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const R=JSON.parse('{"title":"率失真","description":"","frontmatter":{"title":"率失真","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rate-distortion.md","filePath":"cs/rate-distortion.md","lastUpdated":1791413859000}'),d={name:"cs/rate-distortion.md"};function p(C,a,h,m,F,c){const o=D("Mermaid");return t(),A("div",null,[a[2]||(a[2]=n('<h1 id="率失真" tabindex="-1">率失真 <a class="header-anchor" href="#率失真" aria-label="Permalink to &quot;率失真&quot;">​</a></h1><div class="epigraph"><p>允许平均失真 $\\le D$ 时，每符号最少仍要约 $R(D)=\\min I(X;\\hat X)$ 比特；$D=0$ 退回熵，JPEG 一类有损从这里量。</p><footer>—— 据 Shannon, 1959；Cover and Thomas 整理</footer></div><p><a href="/cs/ldpc-turbo">上一课</a>把逼近容量的码钉到直觉。无损路径从信源定理到 LZ、信道从容量到 LDPC。缺口是<strong>有损</strong>：像素不必精确复原。率失真函数 \\(R(D)\\)。本课钉定义与高斯例子，不写编解码器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>失真 \\(d(x,\\hat x)\\)（平方、汉明）。\\(R(D)=\\min_{p(\\hat x|x):\\ \\mathbb{E}d\\le D}I(X;\\hat X)\\)。\\(D=0\\) 且 \\(d\\) 为汉明时 \\(R(0)=H(X)\\)。高斯、平方失真：\\(R(D)=\\frac12\\log(\\sigma^2/D)\\)（\\(D\\le\\sigma^2\\)）。反向：给速率 \\(R\\) 能达到的最小失真。存在性仍随机码；JPEG 量化是启发式逼近，不是 \\(R(D)\\) 的证明。<span class="marginnote">数字实例：取高斯源方差 \\(\\sigma^2=10000\\)、允许平方失真 \\(D=100\\)，则 \\(R(D)=\\frac12\\log_2(10000/100)=\\frac12\\log_2 100\\approx 3.32\\) 比特/样本。也就是说允许 1% 的相对误差，速率就从「无限」砍到约 3.3 比特——有损压缩的红利主要来自头几个比特。</span></p><p><span class="marginnote">直觉类比：把 \\(R(D)\\) 想成一条「预算换保真度」的价目表——预算 \\(D\\) 是你愿意忍受的模糊程度，\\(R(D)\\) 是照这个模糊度做买卖的理论最低价。实践编解码器（JPEG、Opus）是这个价目表的采购报价，只会贵、不会低于它；报价低于价目表，说明合同（失真度量）被偷换了。</span></p><p>与容量：信道是固定 \\(p(y|x)\\) 选 \\(p(x)\\)；率失真是固定 \\(p(x)\\) 选「试验信道」\\(p(\\hat x|x)\\)。对偶。</p><h3 id="失真不是「看起来差不多」" tabindex="-1">失真不是「看起来差不多」 <a class="header-anchor" href="#失真不是「看起来差不多」" aria-label="Permalink to &quot;失真不是「看起来差不多」&quot;">​</a></h3><p>必须先约定 \\(d\\)。感知上好的图可能平方误差大。本课不进视觉模型。</p><p><span class="marginnote">Shannon 1959 率失真。Cover–Thomas 第 10 章。Berger 的书。本课不证着色、高分辨近似全文。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画 \\(R(D)\\) 下降曲线。指出：量化器 + 熵编码是实践上界，未必等于 \\(R(D)\\)。向量量化以块逼近。不要把压缩比写成 \\(R(D)\\)——缺 \\(D\\) 的数。</p>',12)),(t(),s(l,null,{default:e(()=>[B(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E4%BF%A1%E6%BA%90%20X%22%5D%20--%3E%20D%5B%22%E5%85%81%E8%AE%B8%E5%A4%B1%E7%9C%9F%20D%22%5D%0A%20%20D%20--%3E%20RD%5B%22R(D)%3Dmin%20I(X%3BX%CC%82)%22%5D%0A%20%20RD%20--%3E%20LOSSY%5B%22%E6%9C%89%E6%8D%9F%E7%A0%81%E9%80%9F%E7%8E%87%E4%B8%8B%E7%95%8C%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"信息单元的无损/有噪/有损三块至此齐：下界分别是 \\(H\\)、\\(C\\)、\\(R(D)\\)。下一课 KL 把「用错模型」的额外比特钉成相对熵，给交叉熵与最大熵铺路。",-1)),a[5]||(a[5]=E("p",null,"\\(R(D)\\) 不可计算一般形式；构造性仍难。本课当尺子。",-1)),a[6]||(a[6]=E("p",null,"反向水灌：高斯独立分量把速率分给方差大的轴。高分辨量化：\\(R(D)\\approx h(X)-\\log D+\\) 常数。实践：变换 + 量化 + 熵编码给出 \\(R(D)\\) 的上界。没有 \\(d(\\cdot,\\cdot)\\) 的数，谈不上「压了多少信息」。",-1)),(t(),s(l,null,{default:e(()=>[B(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E9%AB%98%E6%96%AF%E7%8B%AC%E7%AB%8B%E5%88%86%E9%87%8F%EF%BC%9A%E6%96%B9%E5%B7%AE%E6%9C%89%E5%A4%A7%E6%9C%89%E5%B0%8F%22%5D%20--%3E%20B%5B%22%E7%BB%99%E5%AE%9A%E6%80%BB%E5%A4%B1%E7%9C%9F%E9%A2%84%E7%AE%97%20D%22%5D%0A%20%20B%20--%3E%20C%7B%22%E8%AF%A5%E5%88%86%E9%87%8F%E6%96%B9%E5%B7%AE%E6%98%AF%E5%90%A6%E8%B6%85%E8%BF%87%20D%EF%BC%9F%22%7D%0A%20%20C%20--%3E%7C%22%E5%90%A6%EF%BC%8C%E6%96%B9%E5%B7%AE%E5%B0%8F%E4%BA%8E%E7%AD%89%E4%BA%8E%20D%22%7C%20N%5B%22%E8%AF%A5%E8%BD%B4%E7%9B%B4%E6%8E%A5%E7%BD%AE%E9%9B%B6%EF%BC%8C%E4%B8%8D%E8%8A%B1%E6%AF%94%E7%89%B9%22%5D%0A%20%20C%20--%3E%7C%22%E6%98%AF%EF%BC%8C%E6%96%B9%E5%B7%AE%E5%A4%A7%E4%BA%8E%20D%22%7C%20W%5B%22%E8%AF%A5%E8%BD%B4%E5%90%B8%E6%94%B6%E5%A4%B1%E7%9C%9F%20D%EF%BC%8C%E5%8F%AA%E7%95%99%20%CF%83%C2%B2-D%22%5D%0A%20%20W%20--%3E%20R%5B%22%E8%AF%A5%E8%BD%B4%E9%80%9F%E7%8E%87%20%C2%BD%20log(%CF%83%C2%B2%2FD)%22%5D%0A%20%20R%20--%3E%20T%5B%22%E5%A4%A7%E6%96%B9%E5%B7%AE%E8%BD%B4%E6%8B%BF%E8%B5%B0%E7%BB%9D%E5%A4%A7%E9%83%A8%E5%88%86%E6%AF%94%E7%89%B9%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">常见误区：初学者容易把「压缩比 10:1」当成信息论结论。压缩比只说了输出/输入的比特数之比，没说失真 \\(D\\) 是多少、也没说 \\(d\\) 是什么——同一压缩比下，压人脸和压噪声图的信息含量完全不同。只有带上失真度量的 \\(R(D)\\) 才是有意义的下界。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 JPEG 标记，不引入感知编码标准。不把大模型的重建损失当 \\(R(D)\\)。后课默认：有损的信息下界是 \\(R(D)\\)。下一课 KL 与交叉熵。</p><p>\\(D=0\\) 回到无损 \\(H\\)；允许失真后 \\(R(D)\\) 下降。没有事先约定的 \\(d\\)，有损比没有信息论意义。实践编解码是上界，高斯平方给出少数闭式。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(R(D)\\) 是失真 \\(D\\) 下的最小互信息速率。</li><li>\\(D=0\\) 回到无损熵；高斯平方有闭式。</li><li>实践编解码给出上界，不是定义。</li><li>出处：Shannon, 1959；Cover and Thomas。</li></ul>',6))])}const f=i(d,[["render",p]]);export{R as __pageData,f as default};
